specimens.css:
/* 状态模拟：:hover 无法静态触发，下面是 Rows.module.css 中 `.sessionRow:hover` / `.sessionRow.menuOpen` / `.projectRow:hover` 相关规则的原样副本，挂在 .hoverRow 上。 */
.sessionRow.hoverRow { background: var(--dsw-alias-interactive-bg-hover); }
.sessionRow.hoverRow .rowActions { display: inline-flex; }
.sessionRow.hoverRow .time,
.sessionRow.hoverRow .pinIndicator { display: none; }
.sessionRow.hoverRow .title { text-overflow: clip; }

.projectRow.hoverRow { background: var(--dsw-alias-interactive-bg-hover); }
.projectRow.hoverRow .chevron { display: inline-flex; }
.projectRow.hoverRow .folder { display: none; }
.projectRow.hoverRow .rowActions { display: inline-flex; }

.searchResultRow.hoverRow { background: var(--dsw-alias-interactive-bg-hover); }
.searchResultRow.hoverRow .rowActions { display: inline-flex; }

